CREATE UNIQUE INDEX vehicles_workshop_client_id ON vehicles(workshop_id,id,client_id);
CREATE TABLE service_orders(id TEXT PRIMARY KEY NOT NULL,workshop_id TEXT NOT NULL REFERENCES workshops(id),client_id TEXT NOT NULL,vehicle_id TEXT NOT NULL,number INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','diagnosing','awaiting_approval','awaiting_appointment','appointment_confirmed','awaiting_part','repairing','finished','delivered','cancelled')), customer_complaint TEXT NOT NULL, diagnosis TEXT, notes TEXT,appointment_requested_at TEXT,appointment_confirmed_at TEXT,payment_method TEXT NOT NULL DEFAULT 'not_defined', payment_terms TEXT NOT NULL DEFAULT '', surcharge_percent REAL NOT NULL DEFAULT 0 CHECK(surcharge_percent BETWEEN 0 AND 100), surcharge_reason TEXT NOT NULL DEFAULT '', deferred_without_deposit INTEGER NOT NULL DEFAULT 0, pix_discount_percent REAL NOT NULL DEFAULT 0, term_revision TEXT NOT NULL DEFAULT (lower(hex(randomblob(16)))), acceptance_at TEXT, acceptance_total REAL,opened_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(workshop_id,id),UNIQUE(workshop_id,number),FOREIGN KEY(workshop_id,client_id) REFERENCES clients(workshop_id,id), FOREIGN KEY(workshop_id,vehicle_id,client_id) REFERENCES vehicles(workshop_id,id,client_id));
CREATE INDEX service_orders_workshop_date ON service_orders(workshop_id,opened_at);
CREATE TABLE budgets(id TEXT PRIMARY KEY NOT NULL,workshop_id TEXT NOT NULL REFERENCES workshops(id),client_id TEXT NOT NULL,vehicle_id TEXT NOT NULL,service_order_id TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','approved','rejected','expired')),payment_method TEXT NOT NULL DEFAULT 'not_defined', payment_terms TEXT NOT NULL DEFAULT '', surcharge_percent REAL NOT NULL DEFAULT 0 CHECK(surcharge_percent BETWEEN 0 AND 100), surcharge_reason TEXT NOT NULL DEFAULT '', deferred_without_deposit INTEGER NOT NULL DEFAULT 0, pix_discount_percent REAL NOT NULL DEFAULT 0, term_revision TEXT NOT NULL DEFAULT (lower(hex(randomblob(16)))), acceptance_at TEXT, acceptance_total REAL,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(workshop_id,id),FOREIGN KEY(workshop_id,service_order_id) REFERENCES service_orders(workshop_id,id),FOREIGN KEY(workshop_id,client_id) REFERENCES clients(workshop_id,id), FOREIGN KEY(workshop_id,vehicle_id,client_id) REFERENCES vehicles(workshop_id,id,client_id));
CREATE INDEX budgets_workshop_date ON budgets(workshop_id,created_at);
CREATE TABLE budget_items(id TEXT PRIMARY KEY NOT NULL,workshop_id TEXT NOT NULL,budget_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('service','part','labor')),description TEXT NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 1000),quantity REAL NOT NULL CHECK(quantity>0 AND quantity<=10000),unit_price REAL NOT NULL CHECK(unit_price>=0 AND unit_price<=1000000),discount REAL NOT NULL DEFAULT 0 CHECK(discount>=0 AND discount<=round(quantity*unit_price,2)),FOREIGN KEY(workshop_id,budget_id) REFERENCES budgets(workshop_id,id) ON DELETE CASCADE);
CREATE INDEX budget_items_parent ON budget_items(workshop_id,budget_id);
CREATE TRIGGER budget_items_insert AFTER INSERT ON budget_items BEGIN UPDATE budgets SET term_revision=lower(hex(randomblob(16))),acceptance_at=NULL,acceptance_total=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.budget_id AND workshop_id=NEW.workshop_id; END;
CREATE TRIGGER budget_items_update AFTER UPDATE ON budget_items BEGIN UPDATE budgets SET term_revision=lower(hex(randomblob(16))),acceptance_at=NULL,acceptance_total=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.budget_id AND workshop_id=NEW.workshop_id; END;
CREATE TRIGGER budget_items_delete AFTER DELETE ON budget_items BEGIN UPDATE budgets SET term_revision=lower(hex(randomblob(16))),acceptance_at=NULL,acceptance_total=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=OLD.budget_id AND workshop_id=OLD.workshop_id; END;
CREATE TABLE service_order_items(id TEXT PRIMARY KEY NOT NULL,workshop_id TEXT NOT NULL,service_order_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('service','part','labor')),description TEXT NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 1000),quantity REAL NOT NULL CHECK(quantity>0 AND quantity<=10000),unit_price REAL NOT NULL CHECK(unit_price>=0 AND unit_price<=1000000),discount REAL NOT NULL DEFAULT 0 CHECK(discount>=0 AND discount<=round(quantity*unit_price,2)),product_id TEXT,FOREIGN KEY(workshop_id,service_order_id) REFERENCES service_orders(workshop_id,id) ON DELETE CASCADE);
CREATE INDEX service_order_items_parent ON service_order_items(workshop_id,service_order_id);
CREATE TRIGGER service_order_items_insert AFTER INSERT ON service_order_items BEGIN UPDATE service_orders SET term_revision=lower(hex(randomblob(16))),acceptance_at=NULL,acceptance_total=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.service_order_id AND workshop_id=NEW.workshop_id; END;
CREATE TRIGGER service_order_items_update AFTER UPDATE ON service_order_items BEGIN UPDATE service_orders SET term_revision=lower(hex(randomblob(16))),acceptance_at=NULL,acceptance_total=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=NEW.service_order_id AND workshop_id=NEW.workshop_id; END;
CREATE TRIGGER service_order_items_delete AFTER DELETE ON service_order_items BEGIN UPDATE service_orders SET term_revision=lower(hex(randomblob(16))),acceptance_at=NULL,acceptance_total=NULL,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=OLD.service_order_id AND workshop_id=OLD.workshop_id; END;
CREATE TABLE labor_price_catalog(id TEXT PRIMARY KEY NOT NULL,workshop_id TEXT NOT NULL REFERENCES workshops(id),category TEXT NOT NULL,name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),minimum_price REAL NOT NULL CHECK(minimum_price>=0 AND minimum_price<=1000000),maximum_price REAL NOT NULL CHECK(maximum_price>=minimum_price AND maximum_price<=1000000),UNIQUE(workshop_id,name));
CREATE TABLE labor_time_rates(id TEXT PRIMARY KEY NOT NULL,workshop_id TEXT NOT NULL REFERENCES workshops(id),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),hours REAL CHECK(hours>=0 AND hours<=10000),price REAL NOT NULL CHECK(price>=0 AND price<=1000000));
CREATE INDEX labor_rates_workshop ON labor_time_rates(workshop_id,name);
